template <class Call>
bool Run(const core::QueryArguments &a, std::vector<core::AuxRow> &out, Call call) {
  int64_t p1 = 0;
  if (!kit::ArgI64(a, 0, 0, p1))
    return false;
  int64_t p2 = 0;
  if (!kit::ArgI64(a, 1, 0, p2))
    return false;
  std::string p3;
  if (!kit::ArgText(a, 2, p3))
    return false;
  std::string p4;
  if (!kit::ArgText(a, 3, p4))
    return false;
  secq4vgen_result *r = call(p1, p2, reinterpret_cast<const uint8_t *>(p3.data()), p3.size(), reinterpret_cast<const uint8_t *>(p4.data()), p4.size());
  if (!r)
    return false;
  const size_t n = secq4vgen_result_len(r);
  out.reserve(out.size() + n);
  for (size_t i = 0; i < n; ++i) {
    core::AuxRow row;
    {
      int64_t v0 = 0;
      row.values.push_back(secq4vgen_result_c0(r, i, &v0) ? kit::OutI64(v0) : kit::OutNull(core::AuxType::Int64));
    }
    {
      const uint8_t *b1 = nullptr;
      size_t l1 = 0;
      row.values.push_back(secq4vgen_result_c1(r, i, &b1, &l1) ? kit::OutText(b1, l1) : kit::OutNull(core::AuxType::String));
    }
    {
      const uint8_t *b2 = nullptr;
      size_t l2 = 0;
      row.values.push_back(secq4vgen_result_c2(r, i, &b2, &l2) ? kit::OutText(b2, l2) : kit::OutNull(core::AuxType::String));
    }
    {
      int64_t v3 = 0;
      row.values.push_back(secq4vgen_result_c3(r, i, &v3) ? kit::OutI64(v3) : kit::OutNull(core::AuxType::Int64));
    }
    {
      uint64_t v4 = 0;
      row.values.push_back(secq4vgen_result_c4(r, i, &v4) ? kit::OutF64(v4) : kit::OutNull(core::AuxType::Double));
    }
    {
      uint64_t v5 = 0;
      row.values.push_back(secq4vgen_result_c5(r, i, &v5) ? kit::OutF64(v5) : kit::OutNull(core::AuxType::Double));
    }
    out.push_back(std::move(row));
  }
  secq4vgen_result_free(r);
  return true;
}

bool Execute(const void *s, const core::QueryArguments &a, std::vector<core::AuxRow> &out) {
  return Run(a, out, [&](auto... x) { return secq4vgen_execute(static_cast<const secq4vgen_state *>(s), x...); });
}

bool Answer(const void *s, const core::QueryArguments &a, std::vector<core::AuxRow> &out) {
  return Run(a, out, [&](auto... x) { return secq4vgens_answer(static_cast<const secq4vgens_reading *>(s), x...); });
}

